#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""MY-HapName —— 内嵌 mtDNA 系统发育树的单文件查询工具。

两棵树的全部数据已经压缩内嵌在本文件末尾，无需任何外部文件和第三方依赖，
把这一个 .py 复制给别人就能直接用。

内嵌数据
--------
    mitotree      Mitotree 20260601（53708 节点，默认树）
    phylotree17   PhyloTree Build 17.2（5439 节点，含旧写法别名表）

两棵树同根 mt-MRCA(RSRS)，都带 macro-haplogroup 注释（v1 详细 / v2 简略），
且共用同一套类别定义，因此两棵树之间的 macro 可以直接比较。

快速上手
--------
    from my_hapname import tree, lineage, children, mrca

    lineage("H1a1")               # 从根到该单倍群的完整上游路径
    children("H1a")               # 直接下游
    descendants("H1a", depth=2)   # 两层以内的所有下游
    mrca("H1a1", "H2a")           # 最近共同祖先
    is_descendant("H1a1", "H")    # H1a1 是否在 H 之下
    info("H1a1")                  # 层级 / 突变 / macro 等汇总
    macro("H1a1")                 # 所属 macro-haplogroup（v2 简略；macro(..., 1) 为 v1 详细）
    by_macro("D")                 # 反查：D 类包含哪些单倍群
    find("H1a")                   # 按名称模糊搜索
    find_by_mutation("A235G")     # 按定义突变搜索

    t = tree("phylotree17")       # 换一棵树，同样的方法全都有
    t.lineage("H1a1")

命令行
------
    python my_hapname.py lineage H1a1
    python my_hapname.py children H1a
    python my_hapname.py descendants H1a --depth 2
    python my_hapname.py mrca H1a1 H2a
    python my_hapname.py info H1a1
    python my_hapname.py find "H1a*"
    python my_hapname.py mutation A235G
    python my_hapname.py macro M7b1a          # v1 与 v2 两套划分一并给出
    python my_hapname.py macro M7b1a H1a1 D4a1   # 可一次查多个
    python my_hapname.py by-macro D
    python my_hapname.py macro-groups
    python my_hapname.py newick H1a > H1a.nwk
    python my_hapname.py --tree phylotree17 lineage H1a1
    python my_hapname.py -t phylotree macro M7b1a    # 树名可用唯一简写

所有查询默认使用 Mitotree；用 --tree/tree() 切换。单倍群名会自动归一化
（大小写不敏感，并套用 PhyloTree 的旧写法别名表，如 "A+152" -> "A_T152C"）。
所有与 macro-haplogroup 有关的输出都同时给出 v1（详细）和 v2（简略）两套划分。
"""

from __future__ import annotations

import base64
import fnmatch
import gzip
import json
import re
import sys
from collections import abc
from functools import lru_cache
from typing import Iterable, Iterator, Sequence

__version__ = "1.0.0"
__all__ = [
    "Tree", "tree", "trees", "resolve_tree", "HaplogroupNotFound",
    "lineage", "ancestors", "parent", "children", "descendants", "siblings",
    "leaves", "is_descendant", "is_ancestor", "mrca", "path", "distance",
    "info", "mutations", "macro", "macros", "by_macro", "macro_groups", "level",
    "find", "find_by_mutation", "newick", "normalize", "exists",
]

DEFAULT_TREE = "mitotree"


class HaplogroupNotFound(KeyError):
    """查询的单倍群不在当前树中。"""

    def __init__(self, name: str, tree_name: str, suggestions: Sequence[str] = ()):
        self.name = name
        self.tree_name = tree_name
        self.suggestions = list(suggestions)
        msg = f"Haplogroup {name!r} not found in {tree_name} / 单倍群 {name!r} 不在 {tree_name} 中"
        if self.suggestions:
            msg += "; did you mean / 是否想查: " + ", ".join(self.suggestions)
        super().__init__(msg)

    def __str__(self) -> str:  # KeyError 默认会给字符串加引号，这里覆盖掉
        return self.args[0]


class Tree:
    """一棵 mtDNA 系统发育树，提供上下游查询。"""

    def __init__(self, payload: dict):
        self.key: str = payload["key"]
        self.name: str = payload["name"]
        self.root: str = payload["root"]
        self.metadata: dict = payload.get("metadata", {})
        self._nodes: dict[str, dict] = payload["nodes"]
        self._aliases: dict[str, str] = payload.get("aliases", {})
        self._children: dict[str, list[str]] | None = None
        self._lower: dict[str, str] | None = None

    # ------------------------------------------------------------------ 基础

    def __repr__(self) -> str:
        return f"<Tree {self.key}: {self.name}, {len(self._nodes)} 个单倍群>"

    def __len__(self) -> int:
        return len(self._nodes)

    def __contains__(self, name: object) -> bool:
        return isinstance(name, str) and self._resolve(name) is not None

    def __iter__(self) -> Iterator[str]:
        return iter(self._nodes)

    @property
    def haplogroups(self) -> list[str]:
        """树中全部单倍群名。"""
        return list(self._nodes)

    def exists(self, name: str) -> bool:
        """名称是否能在本树中解析到某个单倍群。"""
        return self._resolve(name) is not None

    def normalize(self, name: str) -> str:
        """把用户输入的名称归一化为树中的规范名，找不到则抛 HaplogroupNotFound。"""
        return self._require(name)

    # -------------------------------------------------------------- 名称解析

    def _resolve(self, name: str) -> str | None:
        if not isinstance(name, str):
            return None
        raw = name.strip()
        if not raw:
            return None
        if raw in self._nodes:
            return raw
        alias = self._aliases.get(raw)
        if alias in self._nodes:
            return alias
        if self._lower is None:
            # 后出现的同名（大小写不同）不覆盖先出现的，保持稳定
            lower: dict[str, str] = {}
            for hg in self._nodes:
                lower.setdefault(hg.lower(), hg)
            for src, dst in self._aliases.items():
                if dst in self._nodes:
                    lower.setdefault(src.lower(), dst)
            self._lower = lower
        return self._lower.get(raw.lower())

    def _require(self, name: str) -> str:
        hg = self._resolve(name)
        if hg is None:
            raise HaplogroupNotFound(name, self.name, self._suggest(name))
        return hg

    def _suggest(self, name: str, limit: int = 5) -> list[str]:
        raw = str(name).strip().lower()
        if not raw:
            return []
        hits = [hg for hg in self._nodes if raw in hg.lower()]
        if not hits:  # 逐字符截短，找最长的可识别前缀
            for end in range(len(raw) - 1, 0, -1):
                hits = [hg for hg in self._nodes if hg.lower().startswith(raw[:end])]
                if hits:
                    break
        return sorted(hits, key=lambda h: (len(h), h))[:limit]

    # ------------------------------------------------------------ 节点与上游

    def get(self, hg: str) -> dict:
        """该单倍群的原始记录（parent / level / mutations / macro）。"""
        return dict(self._nodes[self._require(hg)])

    def parent(self, hg: str) -> str | None:
        """直接上游；根节点返回 None。"""
        return self._nodes[self._require(hg)]["parent"]

    def lineage(self, hg: str) -> list[str]:
        """从根到该单倍群（含自身）的完整路径。"""
        node = self._require(hg)
        chain = [node]
        seen = {node}
        while True:
            up = self._nodes[chain[-1]]["parent"]
            if up is None:
                break
            if up in seen:  # 数据异常时的保险，正常树不会触发
                raise RuntimeError(f"{self.name} 中检测到环：{up}")
            seen.add(up)
            chain.append(up)
        chain.reverse()
        return chain

    def ancestors(self, hg: str, include_self: bool = False) -> list[str]:
        """全部上游，由近及远排列。"""
        chain = self.lineage(hg)
        if not include_self:
            chain = chain[:-1]
        return chain[::-1]

    def level(self, hg: str) -> int:
        """源数据中标注的层级。"""
        return self._nodes[self._require(hg)]["level"]

    def depth(self, hg: str) -> int:
        """到根的边数（根为 0）。"""
        return len(self.lineage(hg)) - 1

    # ------------------------------------------------------------ 下游与遍历

    def _child_index(self) -> dict[str, list[str]]:
        if self._children is None:
            index: dict[str, list[str]] = {}
            for hg, node in self._nodes.items():
                up = node["parent"]
                if up is not None:
                    index.setdefault(up, []).append(hg)
            for kids in index.values():
                kids.sort()
            self._children = index
        return self._children

    def children(self, hg: str) -> list[str]:
        """直接下游。"""
        return list(self._child_index().get(self._require(hg), ()))

    def descendants(self, hg: str, depth: int | None = None,
                    include_self: bool = False) -> list[str]:
        """全部下游（广度优先）。depth 限制层数，depth=1 等价于 children。"""
        start = self._require(hg)
        index = self._child_index()
        out: list[str] = [start] if include_self else []
        frontier = [start]
        d = 0
        while frontier and (depth is None or d < depth):
            nxt: list[str] = []
            for node in frontier:
                kids = index.get(node, ())
                out.extend(kids)
                nxt.extend(kids)
            frontier = nxt
            d += 1
        return out

    def siblings(self, hg: str) -> list[str]:
        """同一上游下的其他单倍群。"""
        node = self._require(hg)
        up = self._nodes[node]["parent"]
        if up is None:
            return []
        return [c for c in self._child_index().get(up, ()) if c != node]

    def leaves(self, hg: str | None = None) -> list[str]:
        """指定子树（默认整棵树）中的所有叶节点。"""
        index = self._child_index()
        if hg is None:
            return sorted(h for h in self._nodes if h not in index)
        return [h for h in self.descendants(hg, include_self=True) if h not in index]

    def is_descendant(self, hg: str, of: str) -> bool:
        """hg 是否位于 of 之下（同一节点返回 False）。"""
        node, anc = self._require(hg), self._require(of)
        if node == anc:
            return False
        return anc in self.lineage(node)[:-1]

    def is_ancestor(self, hg: str, of: str) -> bool:
        """hg 是否为 of 的上游。"""
        return self.is_descendant(of, hg)

    # ------------------------------------------------------------ 多节点关系

    def mrca(self, *hgs: str) -> str:
        """若干单倍群的最近共同祖先。"""
        names = _flatten(hgs)
        if not names:
            raise ValueError("mrca() 至少需要一个单倍群")
        common = self.lineage(names[0])
        for name in names[1:]:
            other = self.lineage(name)
            n = 0
            for a, b in zip(common, other):
                if a != b:
                    break
                n += 1
            common = common[:n]
            if not common:  # 单根树中不会发生
                raise ValueError("这些单倍群没有共同祖先")
        return common[-1]

    def path(self, a: str, b: str) -> list[str]:
        """两个单倍群之间经过 MRCA 的完整路径。"""
        na, nb = self._require(a), self._require(b)
        anc = self.mrca(na, nb)
        up = self.lineage(na)
        down = self.lineage(nb)
        i = up.index(anc)
        return up[i:][::-1] + down[down.index(anc) + 1:]

    def distance(self, a: str, b: str) -> int:
        """两个单倍群之间的边数。"""
        return len(self.path(a, b)) - 1

    # -------------------------------------------------------------- 突变注释

    def mutations(self, hg: str, cumulative: bool = False) -> list[str]:
        """该单倍群自身定义的突变；cumulative=True 则给出自根累积的全部突变。"""
        if not cumulative:
            return list(self._nodes[self._require(hg)]["mutations"])
        out: list[str] = []
        for node in self.lineage(hg):
            out.extend(self._nodes[node]["mutations"])
        return out

    def macro(self, hg: str, version: int = 2) -> str | None:
        """所属 macro-haplogroup。

        version=2 为简略划分（约 42 类），version=1 为详细划分（约 94 类）。
        名字带 * 表示「该类中未被更细类单列的部分」，如 U* 不含 K、M8* 不含 C 和 Z。
        根节点没有归类，返回 None。
        """
        if version not in (1, 2):
            raise ValueError("version 只能是 1（详细）或 2（简略）")
        node = self._nodes[self._require(hg)]
        return node.get("macro" if version == 2 else "macro_v1")

    def macros(self, hg: str) -> dict[str, str | None]:
        """同时给出两套划分的 macro-haplogroup：{"v1": 详细, "v2": 简略}。"""
        node = self._nodes[self._require(hg)]
        return {"v1": node.get("macro_v1"), "v2": node.get("macro")}

    def by_macro(self, name: str, version: int = 2) -> list[str]:
        """反查：某个 macro-haplogroup 包含哪些单倍群。名称大小写不敏感。"""
        key = "macro" if version == 2 else "macro_v1"
        want = name.strip().lower()
        return sorted(hg for hg, node in self._nodes.items()
                      if (node.get(key) or "").lower() == want)

    def macro_groups(self, version: int = 2) -> dict[str, int]:
        """本树的全部 macro-haplogroup 及其包含的单倍群数。"""
        key = "macro" if version == 2 else "macro_v1"
        counts: dict[str, int] = {}
        for node in self._nodes.values():
            label = node.get(key)
            if label:
                counts[label] = counts.get(label, 0) + 1
        return dict(sorted(counts.items(), key=lambda kv: (-kv[1], kv[0])))

    def info(self, hg: str) -> dict:
        """单个单倍群的汇总信息。"""
        node = self._require(hg)
        rec = self._nodes[node]
        out = {
            "haplogroup": node,
            "tree": self.key,
            "level": rec["level"],
            "depth": self.depth(node),
            "parent": rec["parent"],
            "lineage": self.lineage(node),
            "n_children": len(self._child_index().get(node, ())),
            "children": self.children(node),
            "n_descendants": len(self.descendants(node)),
            "mutations": list(rec["mutations"]),
        }
        if "macro" in rec:
            out["macro_v1"] = rec["macro_v1"]
            out["macro_v2"] = rec["macro"]
        return out

    # ------------------------------------------------------------------ 搜索

    def find(self, pattern: str, regex: bool = False, limit: int | None = None) -> list[str]:
        """按名称搜索。默认大小写不敏感；含 * 或 ? 时按通配符匹配，否则按子串。"""
        if regex:
            rx = re.compile(pattern, re.IGNORECASE)
            hits = [hg for hg in self._nodes if rx.search(hg)]
        elif any(ch in pattern for ch in "*?[]"):
            low = pattern.lower()
            hits = [hg for hg in self._nodes if fnmatch.fnmatch(hg.lower(), low)]
        else:
            low = pattern.lower()
            hits = [hg for hg in self._nodes if low in hg.lower()]
        hits.sort(key=lambda h: (len(h), h))
        return hits[:limit] if limit else hits

    def find_by_mutation(self, *muts: str, mode: str = "all") -> list[str]:
        """找出由指定突变定义的单倍群。

        mode="all" 要求同时携带全部给定突变，"any" 则命中其一即可。
        突变名大小写不敏感，且忽略 PhyloTree 的 ! 和 () 等修饰符。
        """
        wanted = {_norm_mut(m) for m in _flatten(muts)}
        if not wanted:
            raise ValueError("find_by_mutation() 至少需要一个突变")
        if mode not in ("all", "any"):
            raise ValueError("mode 只能是 'all' 或 'any'")
        hits = []
        for hg, node in self._nodes.items():
            have = {_norm_mut(m) for m in node["mutations"]}
            if (wanted <= have) if mode == "all" else (wanted & have):
                hits.append(hg)
        hits.sort(key=lambda h: (len(h), h))
        return hits

    # ------------------------------------------------------------------ 导出

    def newick(self, hg: str | None = None, with_lengths: bool = False) -> str:
        """把子树（默认整棵树）导出为 Newick 字符串。

        with_lengths=True 时以该分支的突变个数作为枝长。
        """
        start = self._require(hg) if hg else self.root
        index = self._child_index()

        def render(node: str) -> str:
            kids = index.get(node, ())
            label = _newick_label(node)
            body = f"({','.join(render(k) for k in kids)}){label}" if kids else label
            if with_lengths and node != start:
                body += f":{len(self._nodes[node]['mutations'])}"
            return body

        sys.setrecursionlimit(max(sys.getrecursionlimit(), 10000))
        return render(start) + ";"

    def to_table(self, hg: str | None = None) -> list[dict]:
        """把子树（默认整棵树）展开为一行一个单倍群的记录表，便于写 TSV/DataFrame。"""
        nodes = self.descendants(hg, include_self=True) if hg else list(self._nodes)
        rows = []
        for node in nodes:
            rec = self._nodes[node]
            row = {
                "haplogroup": node,
                "parent": rec["parent"] or "",
                "level": rec["level"],
                "depth": self.depth(node),
                "mutations": " ".join(rec["mutations"]),
            }
            if "macro" in rec:
                row["macro_v1"] = rec["macro_v1"]
                row["macro_v2"] = rec["macro"]
            rows.append(row)
        return rows


# ---------------------------------------------------------------------- 工具


def _flatten(items: Iterable) -> list[str]:
    """允许 f("A", "B") 与 f(["A", "B"]) 两种写法。"""
    out: list[str] = []
    for item in items:
        if isinstance(item, str):
            out.append(item)
        elif isinstance(item, abc.Iterable):
            out.extend(_flatten(item))
        else:
            raise TypeError(f"无法识别的单倍群参数：{item!r}")
    return out


def _norm_mut(mut: str) -> str:
    """归一化突变写法：去掉 ! ( ) 等修饰符并统一大小写。"""
    return re.sub(r"[!()\s]", "", mut).upper()


def _newick_label(name: str) -> str:
    """Newick 保留字符需要用单引号包裹（内部单引号翻倍）。"""
    if re.search(r"[\s(),:;'\[\]]", name):
        return "'" + name.replace("'", "''") + "'"
    return name


