def resolve_tree(name: str) -> str:
    """把用户给的树名解析为内嵌数据的键，支持简写（phylotree、mito、17…）。"""
    key = re.sub(r"[\s\-_.]", "", str(name).strip().lower())
    if key in _DATA:
        return key
    hits = [k for k in _DATA if k.startswith(key)] or [k for k in _DATA if key in k]
    if len(hits) == 1:
        return hits[0]
    if not hits:
        raise KeyError(f"未知的树 {name!r}；可用：{', '.join(_DATA)}")
    raise KeyError(f"树名 {name!r} 有歧义，同时匹配 {', '.join(hits)}")


@lru_cache(maxsize=None)
def _load(key: str) -> Tree:
    payload = json.loads(gzip.decompress(base64.b64decode(_DATA[key])).decode("utf-8"))
    return Tree(payload)


def tree(name: str = DEFAULT_TREE) -> Tree:
    """按名称取一棵树（结果缓存，重复调用不会重新解压）。

    名称可以简写，只要能唯一匹配：tree("phylotree")、tree("mito") 都可以。
    """
    return _load(resolve_tree(name))


def trees() -> list[str]:
    """本文件内嵌的所有树。"""
    return list(_DATA)


# ------------------------------------------------- 模块级快捷方式（默认树）

def normalize(hg: str, tree_name: str = DEFAULT_TREE) -> str:
    return tree(tree_name).normalize(hg)


def exists(hg: str, tree_name: str = DEFAULT_TREE) -> bool:
    return tree(tree_name).exists(hg)


def lineage(hg: str, tree_name: str = DEFAULT_TREE) -> list[str]:
    return tree(tree_name).lineage(hg)


def ancestors(hg: str, include_self: bool = False, tree_name: str = DEFAULT_TREE) -> list[str]:
    return tree(tree_name).ancestors(hg, include_self)


def parent(hg: str, tree_name: str = DEFAULT_TREE) -> str | None:
    return tree(tree_name).parent(hg)


def children(hg: str, tree_name: str = DEFAULT_TREE) -> list[str]:
    return tree(tree_name).children(hg)


def descendants(hg: str, depth: int | None = None, include_self: bool = False,
                tree_name: str = DEFAULT_TREE) -> list[str]:
    return tree(tree_name).descendants(hg, depth, include_self)


def siblings(hg: str, tree_name: str = DEFAULT_TREE) -> list[str]:
    return tree(tree_name).siblings(hg)


def leaves(hg: str | None = None, tree_name: str = DEFAULT_TREE) -> list[str]:
    return tree(tree_name).leaves(hg)


def is_descendant(hg: str, of: str, tree_name: str = DEFAULT_TREE) -> bool:
    return tree(tree_name).is_descendant(hg, of)


def is_ancestor(hg: str, of: str, tree_name: str = DEFAULT_TREE) -> bool:
    return tree(tree_name).is_ancestor(hg, of)


def mrca(*hgs: str, tree_name: str = DEFAULT_TREE) -> str:
    return tree(tree_name).mrca(*hgs)


def path(a: str, b: str, tree_name: str = DEFAULT_TREE) -> list[str]:
    return tree(tree_name).path(a, b)


def distance(a: str, b: str, tree_name: str = DEFAULT_TREE) -> int:
    return tree(tree_name).distance(a, b)


def info(hg: str, tree_name: str = DEFAULT_TREE) -> dict:
    return tree(tree_name).info(hg)


def mutations(hg: str, cumulative: bool = False, tree_name: str = DEFAULT_TREE) -> list[str]:
    return tree(tree_name).mutations(hg, cumulative)


def macro(hg: str, version: int = 2, tree_name: str = DEFAULT_TREE) -> str | None:
    return tree(tree_name).macro(hg, version)


def macros(hg: str, tree_name: str = DEFAULT_TREE) -> dict[str, str | None]:
    return tree(tree_name).macros(hg)


def by_macro(name: str, version: int = 2, tree_name: str = DEFAULT_TREE) -> list[str]:
    return tree(tree_name).by_macro(name, version)


def macro_groups(version: int = 2, tree_name: str = DEFAULT_TREE) -> dict[str, int]:
    return tree(tree_name).macro_groups(version)


def level(hg: str, tree_name: str = DEFAULT_TREE) -> int:
    return tree(tree_name).level(hg)


def find(pattern: str, regex: bool = False, limit: int | None = None,
         tree_name: str = DEFAULT_TREE) -> list[str]:
    return tree(tree_name).find(pattern, regex, limit)


def find_by_mutation(*muts: str, mode: str = "all", tree_name: str = DEFAULT_TREE) -> list[str]:
    return tree(tree_name).find_by_mutation(*muts, mode=mode)


def newick(hg: str | None = None, with_lengths: bool = False,
           tree_name: str = DEFAULT_TREE) -> str:
    return tree(tree_name).newick(hg, with_lengths)


# ------------------------------------------------------------------ 命令行


def _print_lines(items: Iterable[str]) -> None:
    for item in items:
        print(item)


def _print_table(rows: Sequence[dict], as_json: bool = False) -> None:
    """带表头的 TSV 输出；--json 时改输出记录列表。"""
    if as_json:
        print(json.dumps(list(rows), ensure_ascii=False, indent=2))
        return
    if not rows:
        return
    header = list(rows[0])
    print("\t".join(header))
    for row in rows:
        print("\t".join(str(row.get(col, "")) for col in header))


def _macro_row(t: "Tree", hg: str) -> dict:
    """单个单倍群的 macro 归类，两套划分一并给出。"""
    both = t.macros(hg)
    return {
        "Haplogroup": t.normalize(hg),
        "Macro-Haplogroup-v1": both["v1"] or "",
        "Macro-Haplogroup-v2": both["v2"] or "",
    }


_COLOR_RESET = "\033[0m"
_COLOR_ERROR = "\033[31m"
_COLOR_USAGE = "\033[33m"
_COLOR_SECTION = "\033[36m"
_COLOR_OPTIONAL = "\033[32m"
_COLOR_POSITIONAL = "\033[35m"
_COLOR_TEXT = "\033[37m"


def _use_color(stream) -> bool:
    """仅在终端输出且未设置 NO_COLOR 时着色（管道/重定向不带颜色码）。"""
    import os

    return stream.isatty() and not os.environ.get("NO_COLOR")


def _err(message: str) -> None:
    """彩色错误信息，写到 stderr。"""
    text = f"Error / 错误: {message}"
    if _use_color(sys.stderr):
        text = _COLOR_ERROR + text + _COLOR_RESET
    print(text, file=sys.stderr)


def _make_help_formatter(use_color: bool):
    import argparse

    class _ColoredHelpFormatter(argparse.RawDescriptionHelpFormatter):
        def _wrap(self, text, color):
            return color + text + _COLOR_RESET if use_color and text else text

        # 先按无色文本排版，再给固定位置的文字上色，避免转义码干扰换行与对齐宽度
        def _format_usage(self, usage, actions, groups, prefix):
            text = super()._format_usage(usage, actions, groups, prefix)
            if use_color and text.startswith("usage:"):
                text = self._wrap("usage:", _COLOR_USAGE) + text[len("usage:"):]
            return text

        def start_section(self, heading):
            super().start_section(self._wrap(heading, _COLOR_SECTION))

        def add_text(self, text):
            super().add_text(self._wrap(text, _COLOR_TEXT) if text else text)

        def _format_action(self, action):
            text = super()._format_action(action)
            if not use_color:
                return text
            inv = self._format_action_invocation(action)
            color = _COLOR_OPTIONAL if action.option_strings else _COLOR_POSITIONAL
            return text.replace(inv, self._wrap(inv, color), 1)

    return _ColoredHelpFormatter


_EXAMPLES = (
    "Most common examples / 常用示例:\n"
    "  my_hapname trees                          # List embedded trees / 列出内嵌的树\n"
    "  my_hapname lineage H1a1                   # Path from root to H1a1 / 从根到 H1a1 的上游路径\n"
    "  my_hapname info H1a1                      # Summary (level, mutations, macro) / 层级、突变、macro 等汇总\n"
    "  my_hapname children H1a                   # Direct descendants / 直接下游\n"
    "  my_hapname descendants H1a --depth 2      # Descendants within 2 levels / 两层以内的全部下游\n"
    "  my_hapname mrca H1a1 H2a                  # Most recent common ancestor / 最近共同祖先\n"
    "  my_hapname find \"H1a*\"                    # Search by name (wildcard) / 按名称搜索（支持通配符）\n"
    "  my_hapname mutation A235G                 # Search by defining mutation / 按定义突变搜索\n"
    "  my_hapname macro M7b1a H1a1 D4a1          # Macro-haplogroup v1/v2, many at once / 一次查多个的 macro 归类\n"
    "  my_hapname by-macro D                     # Haplogroups under macro D / 反查 macro D 下的单倍群\n"
    "  my_hapname newick H1a > H1a.nwk           # Export subtree as Newick / 导出 Newick 子树\n"
    "  my_hapname -t phylotree17 lineage H1a1    # Use PhyloTree Build 17 / 改用 PhyloTree Build 17\n"
    "  my_hapname --json info H1a1               # JSON output / 以 JSON 输出\n"
)


def main(argv: Sequence[str] | None = None) -> int:
    import argparse
    from functools import partial

    formatter = partial(_make_help_formatter(_use_color(sys.stdout)))

    parser = argparse.ArgumentParser(
        prog="my_hapname",
        description=("my_hapname - Query mtDNA phylogenetic trees "
                     f"(embedded: {', '.join(_DATA)}). / "
                     f"mtDNA 系统发育树查询工具（内嵌 {', '.join(_DATA)}）。"),
        epilog=_EXAMPLES,
        formatter_class=formatter,
    )
    parser.add_argument("-V", "--version", action="version",
                        version=f"my_hapname v{__version__}",
                        help="Print the version number and exit / 打印版本号后退出")
    parser.add_argument("--tree", "-t", default=DEFAULT_TREE, metavar="TREE",
                        help=f"Tree to use: {' / '.join(_DATA)} (default {DEFAULT_TREE}); "
                             "a unique abbreviation works, e.g. phylotree, mito / "
                             f"使用哪棵树（默认 {DEFAULT_TREE}），可用能唯一匹配的简写")
    parser.add_argument("--json", action="store_true",
                        help="Output as JSON / 以 JSON 输出")
    sub = parser.add_subparsers(dest="cmd", metavar="COMMAND")

    def new(name: str, help_: str) -> argparse.ArgumentParser:
        return sub.add_parser(name, help=help_, description=help_, formatter_class=formatter)

    def add(name: str, help_: str, *args: str) -> argparse.ArgumentParser:
        p = new(name, help_)
        for arg in args:
            p.add_argument(arg, help=_ARG_HELP.get(arg, ""))
        return p

    _ARG_HELP = {
        "haplogroup": "Haplogroup name / 单倍群名",
        "a": "First haplogroup / 第一个单倍群",
        "b": "Second haplogroup / 第二个单倍群",
        "pattern": "Name pattern, e.g. \"H1a*\" / 名称模式，如 \"H1a*\"",
    }

    add("lineage", "Full upstream path from root / 从根到该单倍群的完整上游路径", "haplogroup")
    add("ancestors", "All ancestors, nearest first / 全部上游（由近及远）", "haplogroup")
    add("parent", "Direct parent / 直接上游", "haplogroup")
    add("children", "Direct children / 直接下游", "haplogroup")
    add("siblings", "Other haplogroups under the same parent / 同一上游下的其他单倍群", "haplogroup")
    add("info", "Summary information / 汇总信息", "haplogroup")

    p = new("macro", "Macro-haplogroup (both v1 and v2) / 所属 macro-haplogroup（同时给出 v1 和 v2）")
    p.add_argument("haplogroups", nargs="+", help="One or more haplogroups / 可一次查多个单倍群")

    p = new("by-macro", "Haplogroups under a macro-haplogroup / 反查某个 macro-haplogroup 下的所有单倍群")
    p.add_argument("name", help="Macro-haplogroup name / macro-haplogroup 名称")

    new("macro-groups", "List all macro-haplogroups with counts (v1 and v2) / "
                        "列出全部 macro-haplogroup 及其单倍群数（v1 与 v2）")

    p = add("descendants", "All descendants / 全部下游", "haplogroup")
    p.add_argument("--depth", type=int, default=None,
                   help="Limit levels, 1 equals children / 限制层数，1 等价于 children")

    p = new("leaves", "Leaf nodes of the subtree / 子树中的叶节点")
    p.add_argument("haplogroup", nargs="?", default=None,
                   help="Subtree root (default: whole tree) / 子树根（默认整棵树）")

    p = new("mrca", "Most recent common ancestor / 最近共同祖先")
    p.add_argument("haplogroups", nargs="+", help="Two or more haplogroups / 两个及以上单倍群")

    add("path", "Path between two haplogroups via their MRCA / 两者之间经 MRCA 的路径", "a", "b")
    add("distance", "Number of edges between two haplogroups / 两者之间的边数", "a", "b")

    p = add("mutations", "Defining mutations / 定义突变", "haplogroup")
    p.add_argument("--cumulative", "-c", action="store_true",
                   help="All mutations accumulated from the root / 给出自根累积的全部突变")

    add("is-descendant", "Whether A is under B / 判断 A 是否在 B 之下", "a", "b")

    p = add("find", "Search by name / 按名称搜索", "pattern")
    p.add_argument("--regex", "-r", action="store_true", help="Match as regex / 按正则匹配")
    p.add_argument("--limit", "-n", type=int, default=50,
                   help="Max results, 0 for unlimited (default 50) / 最多输出多少条（默认 50，0 为不限）")

    p = new("mutation", "Search haplogroups by defining mutation / 按定义突变搜索单倍群")
    p.add_argument("mutations", nargs="+", help="One or more mutations, e.g. A235G / 一个或多个突变，如 A235G")
    p.add_argument("--any", dest="any_", action="store_true",
                   help="Match any mutation (default: all) / 命中任一突变即可（默认要求全部命中）")

    p = new("newick", "Export a Newick subtree / 导出 Newick 子树")
    p.add_argument("haplogroup", nargs="?", default=None,
                   help="Subtree root (default: whole tree) / 子树根（默认整棵树）")
    p.add_argument("--lengths", action="store_true",
                   help="Use mutation counts as branch lengths / 以突变个数作为枝长")

    p = new("table", "Export as TSV / 导出为 TSV")
    p.add_argument("haplogroup", nargs="?", default=None,
                   help="Subtree root (default: whole tree) / 子树根（默认整棵树）")

    new("trees", "List embedded trees / 列出内嵌的树")

    args = parser.parse_args(argv)

    if args.cmd is None:
        parser.print_help()
        return 0

    if args.cmd == "trees":
        for key in _DATA:
            t = tree(key)
            print(f"{key}\t{t.name}\t{len(t)} 个单倍群\t根 {t.root}")
        return 0

    try:
        t = tree(args.tree)
    except KeyError as exc:
        _err(str(exc.args[0]))
        return 1

    try:
        if args.cmd == "lineage":
            result = t.lineage(args.haplogroup)
        elif args.cmd == "ancestors":
            result = t.ancestors(args.haplogroup)
        elif args.cmd == "parent":
            result = [t.parent(args.haplogroup) or ""]
        elif args.cmd == "children":
            result = t.children(args.haplogroup)
        elif args.cmd == "siblings":
            result = t.siblings(args.haplogroup)
        elif args.cmd == "descendants":
            result = t.descendants(args.haplogroup, depth=args.depth)
        elif args.cmd == "leaves":
            result = t.leaves(args.haplogroup)
        elif args.cmd == "mrca":
            result = [t.mrca(*args.haplogroups)]
        elif args.cmd == "path":
            result = t.path(args.a, args.b)
        elif args.cmd == "distance":
            result = [str(t.distance(args.a, args.b))]
        elif args.cmd == "mutations":
            result = t.mutations(args.haplogroup, cumulative=args.cumulative)
        elif args.cmd == "macro":
            rows = [_macro_row(t, h) for h in args.haplogroups]
            _print_table(rows, args.json)
            return 0
        elif args.cmd == "by-macro":
            # 两套划分里都找一遍，成员合并后同时列出各自的 v1/v2，便于看出两者差异
            members = sorted(set(t.by_macro(args.name, 1)) | set(t.by_macro(args.name, 2)),
                             key=lambda h: (t.depth(h), h))
            if not members:
                _err(f"No macro-haplogroup {args.name!r} in v1/v2 of {t.name} / "
                     f"{t.name} 的 v1/v2 划分中都没有 macro-haplogroup {args.name!r}")
                return 1
            _print_table([_macro_row(t, h) for h in members], args.json)
            return 0
        elif args.cmd == "macro-groups":
            rows = []
            for version, tag in ((1, "v1"), (2, "v2")):
                for label, n in t.macro_groups(version).items():
                    rows.append({"Version": tag, "Macro-Haplogroup": label, "N": n})
            _print_table(rows, args.json)
            return 0
        elif args.cmd == "is-descendant":
            result = [str(t.is_descendant(args.a, args.b))]
        elif args.cmd == "find":
            result = t.find(args.pattern, regex=args.regex, limit=args.limit or None)
        elif args.cmd == "mutation":
            result = t.find_by_mutation(*args.mutations, mode="any" if args.any_ else "all")
        elif args.cmd == "newick":
            print(t.newick(args.haplogroup, with_lengths=args.lengths))
            return 0
        elif args.cmd == "table":
            _print_table(t.to_table(args.haplogroup), args.json)
            return 0
        elif args.cmd == "info":
            data = t.info(args.haplogroup)
            if args.json:
                print(json.dumps(data, ensure_ascii=False, indent=2))
            else:
                print(f"单倍群\t{data['haplogroup']}")
                print(f"树\t{t.name}")
                print(f"层级\t{data['level']}（到根 {data['depth']} 步）")
                print(f"上游\t{data['parent'] or '（根）'}")
                if "macro_v1" in data:
                    print(f"Macro-Haplogroup-v1\t{data['macro_v1']}")
                    print(f"Macro-Haplogroup-v2\t{data['macro_v2']}")
                print(f"下游\t直接 {data['n_children']} 个，累计 {data['n_descendants']} 个")
                print(f"突变\t{' '.join(data['mutations']) or '（无）'}")
                print(f"路径\t{' > '.join(data['lineage'])}")
                if data["children"]:
                    print(f"直接下游\t{' '.join(data['children'])}")
            return 0
        else:  # pragma: no cover - argparse 已保证
            parser.error(f"unknown command / 未知子命令 {args.cmd}")
    except (HaplogroupNotFound, ValueError) as exc:
        _err(str(exc))
        return 1

    if args.json:
        print(json.dumps(result, ensure_ascii=False, indent=2))
    else:
        _print_lines(result)
    return 0


def _cli() -> int:
    """命令行入口：额外处理 `| head` 之类提前关闭管道的情况。"""
    import os

    def _mute_stdout() -> None:
        # 下游（head/less 等）已关闭管道，把 stdout 指向 devnull，
        # 否则解释器退出时还会再刷一次缓冲区并打印 BrokenPipeError。
        os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())

    try:
        code = main()
    except KeyboardInterrupt:
        return 130
    except BrokenPipeError:
        _mute_stdout()
        return 0
    # 缓冲区里可能还有没落地的内容，这里显式刷一次才能捕获到管道已断
    try:
        sys.stdout.flush()
    except BrokenPipeError:
        _mute_stdout()
        return 0
    return code


if __name__ == "__main__":
    sys.exit(_cli())
